        assertEquals("Booking receipt", document.get("title").asText());
        assertTrue(document.get("text").asText().contains("Guest: John Smith (passport X1234567, United Kingdom)"));
        assertTrue(document.get("text").asText().contains("BRL "));
        assertTrue(document.get("text").asText().contains("nights"));
    }

    @Test
    void requiresExactlyOneIdentificationType() throws Exception {
        String noIdentification = """
                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
                 "checkIn": "2027-07-10", "checkOut": "2027-07-12", "guests": 2, "ratePlan": "STANDARD"}
                """;
        assertEquals(400, post("/reservations", noIdentification).statusCode());

        String twoIdentifications = """
                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
                 "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Test Ltd",
                 "checkIn": "2027-07-10", "checkOut": "2027-07-12", "guests": 2, "ratePlan": "STANDARD"}
                """;
        HttpResponse<String> response = post("/reservations", twoIdentifications);
        assertEquals(400, response.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());

        String onlyCompanyCnpj = """
                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
                 "companyCnpj": "12.345.678/0001-90",
                 "checkIn": "2027-07-10", "checkOut": "2027-07-12", "guests": 2, "ratePlan": "STANDARD"}
                """;
        assertEquals(400, post("/reservations", onlyCompanyCnpj).statusCode());

